// Timezone "simples": considera o servidor em UTC e ajusta pra SP
const now = new Date();

// calcula "amanhã"
const tomorrow = new Date(
  now.getFullYear(),
  now.getMonth(),
  now.getDate() + 1,
  0, 0, 0, 0
);

const start = new Date(
  tomorrow.getFullYear(),
  tomorrow.getMonth(),
  tomorrow.getDate(),
  0, 0, 0, 0
).toISOString();

const end = new Date(
  tomorrow.getFullYear(),
  tomorrow.getMonth(),
  tomorrow.getDate(),
  23, 59, 59, 999
).toISOString();

// lista de profissionais (ajusta com seus iCalUID reais)
const professionals = [
  {
    doctor_name: 'Dr. José Lira',
    calendarId: '99b2dfb64b09000ca4d7b164b4a03207d6aee6f6f6603eeb68f1f3efbfa036fb@group.calendar.google.com'
  },
  {
    doctor_name: 'Dr. Nicolas Martins',
    calendarId: 'f42fa520a6361e2865c762ef986122bd1041192cde2b3fcc4f3d1e6bc0d7d53c@group.calendar.google.com'
  },
];

return professionals.map(p => ({
  json: {
    ...p,
    timeMin: start,
    timeMax: end,
  }
}));

const tz = 'America/Sao_Paulo';

function formatHora(dateTimeStr) {
  const d = new Date(dateTimeStr);
  return d.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit', timeZone: tz });
}

function formatData(dateTimeStr) {
  const d = new Date(dateTimeStr);
  return d.toLocaleDateString('pt-BR', { timeZone: tz });
}

const doctorByCalendar = {
  '99b2dfb64b09000ca4d7b164b4a03207d6aee6f6f6603eeb68f1f3efbfa036fb@group.calendar.google.com': 'Dr. José Lira',
  'f42fa520a6361e2865c762ef986122bd1041192cde2b3fcc4f3d1e6bc0d7d53c@group.calendar.google.com': 'Dr. Nicolas Martins',
};

return items.map(item => {
  const ev = item.json;
  const desc = ev.description || '';
  const summary = ev.summary || '';

  // Tenta extrair telefone da descrição (Padrão: Phone: 55...) ou procura qualquer sequência de celular BR
  let phoneMatch = desc.match(/Phone:\s*(\d+)/i) || desc.match(/(?:55)?\d{2}9\d{8}/);

  // Se não achar na descrição, tenta no título (Summary) como fallback
  if (!phoneMatch) {
      phoneMatch = summary.match(/(?:55)?\d{2}9\d{8}/);
  }

  const phone = phoneMatch ? phoneMatch[0].replace(/\D/g, '') : null;

  // Extrai nome do título (Ex: Cliente Nicolas | ...)
  const nameMatch = summary.match(/Cliente\s*[:|-]?\s*([^|]+)/i);
  const name = nameMatch ? nameMatch[1].trim() : 'Cliente';

  if (!phone) return null; // Pula se não tiver telefone

  const startDateTime = ev.start?.dateTime || ev.start?.date;
  const date = formatData(startDateTime);
  const time = formatHora(startDateTime);

  const organizer = ev.organizer?.email || '';
  // Se não achar o email do organizador na lista, usa o nome que vier no evento ou um genérico
  const doctor_name = doctorByCalendar[organizer] || ev.doctor_name || 'nosso especialista';

  const msg = `Olá, ${name}! 👋\nLembrando que sua consulta com ${doctor_name} está marcada para amanhã, dia ${date}, às ${time}.\nSe precisar remarcar, é só avisar!`;

  return {
    json: {
      event_id: ev.id,
      phone,
      name,
      doctor_name,
      date,
      time,
      msg,
    },
  };
}).filter(i => i !== null);
